#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main() {
    char s[100]; if (scanf("%s", s) != 1) return 0;
    long long n = atoll(s);
    long long sq = n * n;
    char sq_str[100]; sprintf(sq_str, "%lld", sq);
    int d = strlen(s), sq_len = strlen(sq_str);
    long long r_part = 0, l_part = 0;
    if (sq_len >= d) {
        r_part = atoll(sq_str + sq_len - d);
        sq_str[sq_len - d] = '\0';
        if (strlen(sq_str) > 0) l_part = atoll(sq_str);
    }
    if (r_part + l_part == n) printf("Yes\n");
    else printf("No\n");
    return 0;
}

