import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            long n = Long.parseLong(s);
            long sq = n * n;
            String sqStr = Long.toString(sq);
            int d = s.length(), sqLen = sqStr.length();
            long rPart = Long.parseLong(sqStr.substring(Math.max(0, sqLen - d)));
            long lPart = sqLen > d ? Long.parseLong(sqStr.substring(0, sqLen - d)) : 0;
            System.out.println(rPart + lPart == n ? "Yes" : "No");
        }
    }
}

